def gen(rng):
    def enc(idx):
        return str(idx + 1) if idx < 9 else str(idx + 1) + '#'

    def build(limit, p_count, kmax, lo=0, hi=25):
        parts = []
        total = 0
        while True:
            c = enc(rng.randint(lo, hi))
            if rng.random() < p_count:
                c += '(%d)' % rng.randint(2, kmax)
            if total + len(c) > limit:
                break
            parts.append(c)
            total += len(c)
        return ''.join(parts) or '1'

    tests = ['1', '9', '10#', '26#(2)', '1226#24#(2)', '9(4)10#', '110#(3)1', '1(2)1(2)1(2)', '26#(10000)', '10#10#10#', '19#20#21#']
    for limit in (6, 10, 14, 20, 30, 45, 60, 90):
        for _ in range(2):
            tests.append(build(limit, 0.3, 12))
    tests.append(build(60, 0.5, 5, 0, 8))
    tests.append(build(60, 0.5, 5, 9, 25))
    tests.append(build(100000, 0.0, 12))
    tests.append(build(100000, 1.0, 10000))
    tests.append(build(100000, 0.5, 10000))
    tests.append('26#(10000)' * 10000)
    return tests

